modes.detail:
// ============ 为什么要存高度 ============
//
// 平衡因子 = 左子树高 - 右子树高，AVL 要求它只能是 -1、0、1。
//
// 如果每次要判断平衡都现场递归求高度，插入一次就要 O(n) 的额外开销，
// 整体复杂度会退化。所以干脆**在结点里存一个高度字段**，插入时顺便更新，
// 用 O(1) 就能拿到。
//
// 这就是空间换时间的典型：每个结点多 4 个字节，换来判断平衡不用递归。
//
// ============ 空树的高度是多少 ============
//
// 约定成 **0**（而不是 -1）。这样：
//
//   叶子结点高度 = max(0, 0) + 1 = 1
//   只有一个孩子的结点 = max(孩子高, 0) + 1
//
// 式子统一，不用到处特判空指针。

// 数据元素类型
typedef int ElemType;

// AVL 结点：比普通二叉树多一个 height
typedef struct AVLNode
{
// 数据域
    ElemType data;
// 左子树
    struct AVLNode *left;
// 右子树
    struct AVLNode *right;
// 以自己为根的子树高度（空树记 0）
    int height;
} AVLNode, *AVLTree;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

