modes.detail:
// ============ 什么时候用：LL ============
//
// 判断口诀：**从出问题的结点往下走两步，方向都是「左」**，就是 LL。
//
// 插入前是平衡的：
//
//          5                   5
//         /                   /
//        3        插入 1 后   3          ← 5 的左子树高 2，右子树高 0，失衡
//                           /
//                          1
//
// 从 5 往下走：左（到 3）、再左（到 1）→ LL → 用**右单旋**。
//
// 旋转动作（把 3 提上来，5 降下去当它的右孩子）：
//
//          5                    3
//         /        →           / \
//        3                    1   5
//       /
//      1
//
// 为什么这样转完还是 BST？因为中序都是 1 3 5 —— 旋转**不改变中序**，
// 这是它能保持搜索树性质的根本原因。
//
// ============ 代码怎么写 ============
//
// 四步：
//   ① 记住左孩子（它要升上来当新根）
//   ② 把左孩子的右子树接到原来的根上（原来根的左边腾空）
//   ③ 让原来的根成为新根的右孩子
//   ④ 更新这两个结点的高度
//
// 第 ② 步是初学者最容易漏的 —— 少了它，左孩子的右子树就丢了。

// 右单旋（处理 LL 情况），返回新的子树根
AVLTree RotateLL(AVLTree T)
{
// ① 新根就是左孩子
    AVLTree newRoot = T->left;

// ② 把新根的右子树挂到旧根的左边
// 这一步最容易忘。忘了就直接丢一棵子树。
    T->left = newRoot->right;

// ③ 旧根成为新根的右孩子
    newRoot->right = T;

// ④ 更新高度 —— 必须先更新旧根（它现在是孩子了）
// 顺序不能反：更新自己要用到孩子的高度，所以孩子得先算好。
    UpdateHeight(T);
    UpdateHeight(newRoot);

// 返回新根
    return newRoot;
}

modes.short:
// 右单旋（处理 LL 情况），返回新的子树根
AVLTree RotateLL(AVLTree T)
{
// ① 新根就是左孩子
    AVLTree newRoot = T->left;

// ② 把新根的右子树挂到旧根的左边
    T->left = newRoot->right;

// ③ 旧根成为新根的右孩子
    newRoot->right = T;

// ④ 更新高度 —— 必须先更新旧根（它现在是孩子了）
    UpdateHeight(T);
    UpdateHeight(newRoot);

// 返回新根
    return newRoot;
}

