/* ====================================================================
 *  轮到你了：模块 03  RotateLL
 *  作用：麻烦出在「左孩子的左边」，把左孩子提上来当根。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */



/* ======== 测试驱动（已给出，可自行修改） ======== */
/* 验证 RotateLL（右单旋）：5 3 1 */
int main(void)
{
    /* 手工搭出 5 -> 3 -> 1 这条左斜链，避开 AVLInsert 的自动平衡 */
    AVLTree a = (AVLTree)malloc(sizeof(AVLNode));
    AVLTree b = (AVLTree)malloc(sizeof(AVLNode));
    AVLTree c = (AVLTree)malloc(sizeof(AVLNode));

    c->data = 1; c->left = c->right = NULL; c->height = 1;
    b->data = 3; b->left = c; b->right = NULL; b->height = 2;
    a->data = 5; a->left = b; a->right = NULL; a->height = 3;

    printf("旋转前：根 %d，高 %d，平衡因子 %d\n", a->data, a->height, BalanceFactor(a));
    printf("  中序: "); InOrder(a); printf("\n");

    a = RotateLL(a);

    printf("旋转后：根 %d，高 %d，平衡因子 %d\n", a->data, a->height, BalanceFactor(a));
    printf("  中序: "); InOrder(a); printf("\n");
    printf("（中序必须不变：1 3 5 —— 旋转只换父子关系，不换左右顺序）\n");

    FreeTree(a);
    return 0;
}

modes.detail:
// ============ 和 LL 完全镜像 ============
//
// 从出问题的结点往下走两步都是「右」→ RR → 用**左单旋**。
//
//          3                  3
//           \                    \
//            5     插入 7 后       5        ← 3 的右子树高 2，左子树高 0，失衡
//                                  \
//                                   7
//
// 旋转（把 5 提上来）：
//
//        3                      5
//         \        →           / \
//          5                  3   7
//           \
//            7
//
// 代码就是把 LL 的 left / right 全反过来：
//
//   RotateLL：newRoot = T->left;   T->left = newRoot->right;   newRoot->right = T;
//   RotateRR：newRoot = T->right;  T->right = newRoot->left;   newRoot->left = T;
//
// ============ 名字的坑 ============
//
// 注意命名：**LL 用右旋，RR 用左旋** —— 方向和名字是反的。
// 名字说的是"麻烦在哪"（LL = 左孩子的左边），不是"往哪转"。
// 记混了会写出把树转歪的代码，而且往往还能跑，只是不再平衡。

// 左单旋（处理 RR 情况），返回新的子树根
AVLTree RotateRR(AVLTree T)
{
// ① 新根是右孩子
    AVLTree newRoot = T->right;

// ② 新根的左子树改挂到旧根的右边
    T->right = newRoot->left;

// ③ 旧根成为新根的左孩子
    newRoot->left = T;

// ④ 先更新旧根，再更新新根
    UpdateHeight(T);
    UpdateHeight(newRoot);

// 返回新根
    return newRoot;
}

modes.short:
