// ============ 插入的四步 ============
//
//   ① 按 BST 的规矩往下走，走到空位置造结点
//   ② **回溯的路上**更新自己的高度
//   ③ 算平衡因子，如果绝对值到 2 就判断是哪种情况
//   ④ 对应的旋转，返回新的子树根
//
// 关键在于**第 ② 步的位置**：更新高度必须在递归回来之后、
// 也就是"孩子都处理好了"，这正是后序的顺序。
//
// ============ 谁先失衡 ============
//
// 插入只会让**从新结点到根这条路径上**的结点失衡，而且
// **最先失衡的一定是离新结点最近的那个**。
//
// 递归回溯天然是从下往上走的，所以遇到的第一个失衡结点就是它 ——
// 转它一次，整棵树就恢复平衡了（不需要继续往上修）。
// 这也是 AVL 插入只要 O(log n) 的原因。
//
// ============ 判断属于哪种情况 ============
//
// 先看平衡因子：
//
//   左高（BF > 1）→ 麻烦在左边，再看左孩子的哪边高
//        左孩子的左边高（BF(左孩子) >= 0）→ LL
//        左孩子的右边高（BF(左孩子) <  0）→ LR
//
//   右低（BF < -1）→ 麻烦在右边，对称处理
//
// 注意判断用的是**左孩子的平衡因子**，不是"新插入的值比左孩子大还是小" ——
// 两者有时结论不同，用平衡因子才可靠。

// 插入 x，返回新的子树根
AVLTree AVLInsert(AVLTree T, ElemType x)
{
// ① 走到空位置，造结点（新结点高度是 1）
    if (T == NULL)
    {
        AVLTree node = (AVLTree)malloc(sizeof(AVLNode));
        if (node == NULL)
        {
            printf("内存分配失败\n");
            exit(1);
        }
        node->data = x;
        node->left = NULL;
        node->right = NULL;
        node->height = 1;
        return node;
    }

// 比当前小 → 插到左子树
    if (x < T->data)
    {
        T->left = AVLInsert(T->left, x);
    }
// 比当前大 → 插到右子树
    else if (x > T->data)
    {
        T->right = AVLInsert(T->right, x);
    }
// 相等 → 不插（和 BST 一致）
    else
    {
        return T;
    }

// ② 回溯到这一步时孩子已经处理好了，更新自己的高度
    UpdateHeight(T);

// ③ 算平衡因子，看有没有失衡
    {
// 平衡因子
        int bf = BalanceFactor(T);

// 左边太高
        if (bf > 1)
        {
// 再看左孩子：左边高是 LL，右边高是 LR
// 用 >= 0 而不是 > 0，是为了把"左孩子平衡"也归到 LL ——
// 那种情况下单旋就够了。
            if (BalanceFactor(T->left) >= 0)
            {
// LL：右单旋
                return RotateLL(T);
            }
// LR：先左后右的双旋
            return RotateLR(T);
        }

// 右边太高（镜像处理）
        if (bf < -1)
        {
// 右孩子右边高是 RR，左边高是 RL
            if (BalanceFactor(T->right) <= 0)
            {
// RR：左单旋
                return RotateRR(T);
            }
// RL：先右后左的双旋
            return RotateRL(T);
        }
    }

// ④ 没失衡，原样返回
    return T;
}

