# 插入 x，返回新的子树根
def AVLInsert(T, x):
# ① 走到空位置，造结点（新结点高度是 1）
    if T is None:
# 造结点：数据填 x，左右是 None，高度 1（C 那边要 malloc 完再一个个填）
        return AVLNode(x)

# 比当前小 → 插到左子树
    if x < T.data:
        T.left = AVLInsert(T.left, x)
# 比当前大 → 插到右子树
    elif x > T.data:
        T.right = AVLInsert(T.right, x)
# 相等 → 不插（和 BST 一致）
    else:
        return T

# ② 回溯到这一步时孩子已经处理好了，更新自己的高度
    UpdateHeight(T)

# ③ 算平衡因子，看有没有失衡
# 平衡因子
    bf = BalanceFactor(T)

# 左边太高
    if bf > 1:
# 再看左孩子：左边高是 LL，右边高是 LR
        if BalanceFactor(T.left) >= 0:
# LL：右单旋
            return RotateLL(T)
# LR：先左后右的双旋
        return RotateLR(T)

# 右边太高（镜像处理）
    if bf < -1:
# 右孩子右边高是 RR，左边高是 RL
        if BalanceFactor(T.right) <= 0:
# RR：左单旋
            return RotateRR(T)
# RL：先右后左的双旋
        return RotateRL(T)

# ④ 没失衡，原样返回
    return T

