modes.detail:
// ============ 验证 AVL 的两把尺子 ============
//
// 写完 AVL 要用两个条件自查：
//
//   ① 中序递增          → 还是 BST（旋转不改变中序）
//   ② 每个结点都平衡     → 确实做到了 AVL 的要求
//
// 第一个用 InOrder 看输出，第二个就是这个函数。
// 两个都过，这棵树才合格。
//
// 只查根是不够的 —— 旋转写出问题时，往往是某个子树里失衡，
// 而根看起来还正常。

// 检查每个结点的平衡因子是否都在 -1..1
// 返回 1 表示全部合法
int CheckBalance(AVLTree T)
{
// 空树算合法
    if (T == NULL)
    {
        return 1;
    }
// 自己失衡就直接返回 0
// 平衡因子的绝对值超过 1 就是不合格的 AVL。
    if (BalanceFactor(T) > 1 || BalanceFactor(T) < -1)
    {
        printf("  结点 %d 失衡，平衡因子 = %d\n", T->data, BalanceFactor(T));
        return 0;
    }
// 两个孩子也都要合法
    return CheckBalance(T->left) && CheckBalance(T->right);
}

