#include <stdio.h>
#include <stdlib.h>


// 数据元素类型
typedef int ElemType;

// AVL 结点：比普通二叉树多一个 height
typedef struct AVLNode
{
// 数据域
    ElemType data;
// 左子树
    struct AVLNode *left;
// 右子树
    struct AVLNode *right;
// 以自己为根的子树高度（空树记 0）
    int height;
} AVLNode, *AVLTree;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;


// 取高度：空树是 0
int GetHeight(AVLTree T)
{
// 空树高度 0
    if (T == NULL)
    {
        return 0;
    }
// 否则就是存着的那个值
    return T->height;
}

// 取两个数的较大者
int MaxInt(int a, int b)
{
    return a > b ? a : b;
}

// 重新计算 T 的高度并写回
void UpdateHeight(AVLTree T)
{
// 空树不用管
    if (T == NULL)
    {
        return;
    }
// 高度 = 两个孩子里高的那个 + 1
    T->height = MaxInt(GetHeight(T->left), GetHeight(T->right)) + 1;
}

// 平衡因子 = 左高 - 右高
int BalanceFactor(AVLTree T)
{
// 空树认为平衡
    if (T == NULL)
    {
        return 0;
    }
// 左减右
    return GetHeight(T->left) - GetHeight(T->right);
}


// 右单旋（处理 LL 情况），返回新的子树根
AVLTree RotateLL(AVLTree T)
{
// ① 新根就是左孩子
    AVLTree newRoot = T->left;

// ② 把新根的右子树挂到旧根的左边
    T->left = newRoot->right;

// ③ 旧根成为新根的右孩子
    newRoot->right = T;

// ④ 更新高度 —— 必须先更新旧根（它现在是孩子了）
    UpdateHeight(T);
    UpdateHeight(newRoot);

// 返回新根
    return newRoot;
}


// 左单旋（处理 RR 情况），返回新的子树根
AVLTree RotateRR(AVLTree T)
{
// ① 新根是右孩子
    AVLTree newRoot = T->right;

// ② 新根的左子树改挂到旧根的右边
    T->right = newRoot->left;

// ③ 旧根成为新根的左孩子
    newRoot->left = T;

// ④ 先更新旧根，再更新新根
    UpdateHeight(T);
    UpdateHeight(newRoot);

// 返回新根
    return newRoot;
}


// 左右双旋（处理 LR），返回新的子树根
AVLTree RotateLR(AVLTree T)
{
// 第一步：先对左孩子做左单旋，把 LR 掰成 LL
    T->left = RotateRR(T->left);

// 第二步：再对自己做右单旋（这一步就是 LL 的处理方式）
    return RotateLL(T);
}


// 右左双旋（处理 RL），返回新的子树根
AVLTree RotateRL(AVLTree T)
{
// 第一步：先对右孩子做右单旋，把 RL 掰成 RR
    T->right = RotateLL(T->right);

// 第二步：再对自己做左单旋
    return RotateRR(T);
}


// 插入 x，返回新的子树根
AVLTree AVLInsert(AVLTree T, ElemType x)
{
// ① 走到空位置，造结点（新结点高度是 1）
    if (T == NULL)
    {
        AVLTree node = (AVLTree)malloc(sizeof(AVLNode));
        if (node == NULL)
        {
            printf("内存分配失败\n");
            exit(1);
        }
        node->data = x;
        node->left = NULL;
        node->right = NULL;
        node->height = 1;
        return node;
    }

// 比当前小 → 插到左子树
    if (x < T->data)
    {
        T->left = AVLInsert(T->left, x);
    }
// 比当前大 → 插到右子树
    else if (x > T->data)
    {
        T->right = AVLInsert(T->right, x);
    }
// 相等 → 不插（和 BST 一致）
    else
    {
        return T;
    }

// ② 回溯到这一步时孩子已经处理好了，更新自己的高度
    UpdateHeight(T);

// ③ 算平衡因子，看有没有失衡
    {
// 平衡因子
        int bf = BalanceFactor(T);

// 左边太高
        if (bf > 1)
        {
// 再看左孩子：左边高是 LL，右边高是 LR
            if (BalanceFactor(T->left) >= 0)
            {
// LL：右单旋
                return RotateLL(T);
            }
// LR：先左后右的双旋
            return RotateLR(T);
        }

// 右边太高（镜像处理）
        if (bf < -1)
        {
// 右孩子右边高是 RR，左边高是 RL
            if (BalanceFactor(T->right) <= 0)
            {
// RR：左单旋
                return RotateRR(T);
            }
// RL：先右后左的双旋
            return RotateRL(T);
        }
    }

// ④ 没失衡，原样返回
    return T;
}


// 中序遍历，顺便看是不是有序
void InOrder(AVLTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }
// 左
    InOrder(T->left);
// 根
    printf("%d ", T->data);
// 右
    InOrder(T->right);
}


// 后序释放
void FreeTree(AVLTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }
// 先孩子
    FreeTree(T->left);
    FreeTree(T->right);
// 后自己
    free(T);
}


// 检查每个结点的平衡因子是否都在 -1..1
int CheckBalance(AVLTree T)
{
// 空树算合法
    if (T == NULL)
    {
        return 1;
    }
// 自己失衡就直接返回 0
    if (BalanceFactor(T) > 1 || BalanceFactor(T) < -1)
    {
        printf("  结点 %d 失衡，平衡因子 = %d\n", T->data, BalanceFactor(T));
        return 0;
    }
// 两个孩子也都要合法
    return CheckBalance(T->left) && CheckBalance(T->right);
}


// 主函数
int main(void)
{
// 故意用有序序列 —— 这正是普通 BST 会退化的情况
    static const int ins[] = { 1, 2, 3, 4, 5, 6, 7 };
// 计数
    int i;
// 树根
    AVLTree T = NULL;

// 打印说明
    printf("插入序列：1 2 3 4 5 6 7（普通 BST 会退化成一条链）\n\n");

// 逐个插入并观察
    for (i = 0; i < 7; i++)
    {
        T = AVLInsert(T, ins[i]);
        printf("插入 %d 后：根 = %d，树高 = %d，中序: ", ins[i], T->data, T->height);
        InOrder(T);
        printf("\n");
    }

// 验证 ①：中序必须递增
    printf("\n① 中序结果：");
    InOrder(T);
    printf("\n   （必须递增 —— 说明旋转没有破坏 BST 性质）\n");

// 验证 ②：树高应该是 3
    printf("\n② 树高 = %d（7 个结点的平衡树应该是 3）\n", T->height);
    printf("   普通 BST 按这个顺序插会变成高度 7 的链\n");

// 验证 ③：每个结点都平衡
    printf("\n③ 逐结点检查平衡因子：");
    if (CheckBalance(T))
    {
        printf("全部在 -1..1 之间，合格\n");
    }

// 释放
    FreeTree(T);
// 正常结束
    return 0;
}

